const lv_img_dsc_t *panel_asset_icon(const char *name,unsigned px) {
 if(!name)return NULL;
 const lv_img_dsc_t *fallback=NULL;
 for(unsigned i=0;i<sizeof(icons)/sizeof(icons[0]);i++) if(!strcmp(name,icons[i].name)){if(icons[i].px==px)return icons[i].img;if(icons[i].px==24)fallback=icons[i].img;}
 return fallback;
}